        };

        context.AddRange(products);

        // sample add 500 products
        // context.AddRange(GetProductsToAdd(500, products));

        context.SaveChanges();
    }

    private static List<Product> GetProductsToAdd(int count, List<Product> baseProducts)
    {
        var productsToAdd = new List<Product>();
        for (int i = 1; i < count; i++)
        {
            foreach (var product in baseProducts)
            {
                var newproduct = new Product
                {
                    Name = $"{product.Name}-{i}",
                    Description = product.Description,
                    ImageUrl = product.ImageUrl,
                    Price = product.Price
                };
                productsToAdd.Add(newproduct);
            }
        }
        return productsToAdd;
    }
}

// File: F:\Dynamic\ExxerAi\ExxerAI\code\MicrosfotSamples\scenarios\08-Sql2025\src\Products\Endpoints\ProductApiActions.cs
using DataEntities;
using Microsoft.AspNetCore.Http;
using Microsoft.EntityFrameworkCore;
using OpenAI.Embeddings;
using Products.Models;
using Products.Models;
using SearchEntities;

namespace Products.Endpoints;

public static class ProductApiActions
{
    public static async Task<IResult> GetAllProducts(Products.Models.Context db)
    {
        var products = await db.Product.ToListAsync();
        return Results.Ok(products);
    }

    public static async Task<IResult> GetProductById(int id, Products.Models.Context db)
    {
        var model = await db.Product.AsNoTracking().FirstOrDefaultAsync(m => m.Id == id);
        return model is not null ? Results.Ok(model) : Results.NotFound();
    }

    public static async Task<IResult> UpdateProduct(int id, Product product, Products.Models.Context db)
    {
        var existing = await db.Product.FirstOrDefaultAsync(m => m.Id == id);
        if (existing == null)
            return Results.NotFound();
        existing.Name = product.Name;
        existing.Description = product.Description;
        existing.Price = product.Price;
        existing.ImageUrl = product.ImageUrl;
        await db.SaveChangesAsync();
        return Results.Ok();
    }

    public static async Task<IResult> CreateProduct(Product product, Products.Models.Context db)
    {
        db.Product.Add(product);
        await db.SaveChangesAsync();
        return Results.Created($"/api/Product/{product.Id}", product);
    }

    public static async Task<IResult> DeleteProduct(int id, Products.Models.Context db)
    {
        var affected = await db.Product
            .Where(m => m.Id == id)
            .ExecuteDeleteAsync();
        return affected == 1 ? Results.Ok() : Results.NotFound();
    }

    public static async Task<IResult> SearchAllProducts(string search, Products.Models.Context db)
    {
        List<Product> products = await db.Product
            .Where(p => EF.Functions.Like(p.Name, $"%{search}%"))
            .ToListAsync();

        var response = new SearchResponse
        {
            Products = products,
            Response = products.Count > 0 ?
                $"{products.Count} Products found for [{search}]" :
                $"No products found for [{search}]"
        };
        return Results.Ok(response);
    }

    public static async Task<IResult> AISearch(string search, Context db, EmbeddingClient embeddingClient, int dimensions = 1536)
    {
        Console.WriteLine("Querying for similar products...");

        var embeddingSearch = embeddingClient.GenerateEmbedding(search, new() { Dimensions = dimensions });
        var vectorSearch = embeddingSearch.Value.ToFloats().ToArray();
        var products = await db.Product
            .OrderBy(p => EF.Functions.VectorDistance("cosine", p.Embedding, vectorSearch))
            .Take(3)
            .ToListAsync();

        var response = new SearchResponse
        {
            Products = products,
            Response = products.Count > 0 ?
                $"{products.Count} Products found for [{search}]" :
                $"No products found for [{search}]"
        };
        return Results.Ok(response);

    }
}


// File: F:\Dynamic\ExxerAi\ExxerAI\code\MicrosfotSamples\scenarios\08-Sql2025\src\Products\Endpoints\ProductEndpoints.cs
﻿using SearchEntities;
using DataEntities;

namespace Products.Endpoints;

public static class ProductEndpoints
{
    /// <summary>
    /// Configures the product-related endpoints for the application.
    /// </summary>
    /// <param name="routes">The route builder to add the endpoints to.</param>
    ///
    /// <remarks>
    /// This method sets up the following endpoints:
    /// 
    /// GET /api/Product/
    /// - Retrieves all products.
    /// - Response: 200 OK with a list of products.
    ///
    /// GET /api/Product/{id}
    /// - Retrieves a product by its ID.
    /// - Response: 200 OK with the product if found, 404 Not Found otherwise.
    ///
    /// PUT /api/Product/{id}
    /// - Updates an existing product by its ID.
    /// - Response: 200 OK if the product is updated, 404 Not Found otherwise.
    ///
    /// POST /api/Product/
    /// - Creates a new product.
    /// - Response: 201 Created with the created product.
    ///
    /// DELETE /api/Product/{id}
    /// - Deletes a product by its ID.
    /// - Response: 200 OK if the product is deleted, 404 Not Found otherwise.
    ///
    /// GET /api/Product/search/{search}
    /// - Searches for products by name.
    /// - Response: 200 OK with a list of matching products and search metadata.
    ///
    /// GET /api/aisearch/{search}
    /// - Searches for products using AI-based search.
    /// - Response: 200 OK with the search results, 404 Not Found otherwise.
    /// </remarks>
    public static void MapProductEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/Product");

        group.MapGet("/", ProductApiActions.GetAllProducts)
            .WithName("GetAllProducts")
            .Produces<List<Product>>(StatusCodes.Status200OK);

        group.MapGet("/{id}", ProductApiActions.GetProductById)
            .WithName("GetProductById")
            .Produces<Product>(StatusCodes.Status200OK)
            .Produces(StatusCodes.Status404NotFound);

        group.MapPut("/{id}", ProductApiActions.UpdateProduct)
            .WithName("UpdateProduct")
            .Produces(StatusCodes.Status404NotFound)
            .Produces(StatusCodes.Status204NoContent);

        group.MapPost("/", ProductApiActions.CreateProduct)
            .WithName("CreateProduct")
            .Produces<Product>(StatusCodes.Status201Created);

        group.MapDelete("/{id}", ProductApiActions.DeleteProduct)
            .WithName("DeleteProduct")
            .Produces<Product>(StatusCodes.Status200OK)
            .Produces(StatusCodes.Status404NotFound);

        group.MapGet("/search/{search}", ProductApiActions.SearchAllProducts)
            .WithName("SearchAllProducts")
            .Produces<List<Product>>(StatusCodes.Status200OK);

        routes.MapGet("/api/aisearch/{search}", ProductApiActions.AISearch)
            .WithName("AISearch")
            .Produces<SearchResponse>(StatusCodes.Status200OK)
            .Produces(StatusCodes.Status404NotFound);
    }
}


