}


public static class DbInitializer
{
    public static void Initialize(ProductDataContext context)
    {
        if (context.Product.Any())
            return;

        var products = new List<Product>
        {
            new Product { Name = "Solar Powered Flashlight", Description = "A fantastic product for outdoor enthusiasts", Price = 19.99m, ImageUrl = "product1.png" },
            new Product { Name = "Hiking Poles", Description = "Ideal for camping and hiking trips", Price = 24.99m, ImageUrl = "product2.png" },
            new Product { Name = "Outdoor Rain Jacket", Description = "This product will keep you warm and dry in all weathers", Price = 49.99m, ImageUrl = "product3.png" },
            new Product { Name = "Survival Kit", Description = "A must-have for any outdoor adventurer", Price = 99.99m, ImageUrl = "product4.png" },
            new Product { Name = "Outdoor Backpack", Description = "This backpack is perfect for carrying all your outdoor essentials", Price = 39.99m, ImageUrl = "product5.png" },
            new Product { Name = "Camping Cookware", Description = "This cookware set is ideal for cooking outdoors", Price = 29.99m, ImageUrl = "product6.png" },
            new Product { Name = "Camping Stove", Description = "This stove is perfect for cooking outdoors", Price = 49.99m, ImageUrl = "product7.png" },
            new Product { Name = "Camping Lantern", Description = "This lantern is perfect for lighting up your campsite", Price = 19.99m, ImageUrl = "product8.png" },
            new Product { Name = "Camping Tent", Description = "This tent is perfect for camping trips", Price = 99.99m, ImageUrl = "product9.png" },
        };

        context.AddRange(products);

        // sample add 500 products
        // context.AddRange(GetProductsToAdd(500, products));

        context.SaveChanges();
    }

    private static List<Product> GetProductsToAdd(int count, List<Product> baseProducts)
    {
        var productsToAdd = new List<Product>();
        for (int i = 1; i < count; i++)
        {
            foreach (var product in baseProducts)
            {
                var newproduct = new Product
                {
                    Name = $"{product.Name}-{i}",
                    Description = product.Description,
                    ImageUrl = product.ImageUrl,
                    Price = product.Price
                };
                productsToAdd.Add(newproduct);
            }
        }
        return productsToAdd;
    }
}

// File: F:\Dynamic\ExxerAi\ExxerAI\code\Samples\MicrosfotSamples\scenarios\04-chromadb\src\Products\Endpoints\ProductEndpoints.cs
﻿using SearchEntities;
using DataEntities;
using Microsoft.EntityFrameworkCore;
using System.Diagnostics;
using Products.Memory;
using Products.Models;
using OpenAI.Embeddings;
using OpenAI.Chat;

namespace Products.Endpoints;

public static class ProductEndpoints
{
    /// <summary>
    /// Configures the product-related endpoints for the application.
    /// </summary>
    /// <param name="routes">The route builder to add the endpoints to.</param>
    ///
    /// <remarks>
    /// This method sets up the following endpoints:
    /// 
    /// GET /api/Product/
    /// - Retrieves all products.
    /// - Response: 200 OK with a list of products.
    ///
    /// GET /api/Product/{id}
    /// - Retrieves a product by its ID.
    /// - Response: 200 OK with the product if found, 404 Not Found otherwise.
    ///
    /// PUT /api/Product/{id}
    /// - Updates an existing product by its ID.
    /// - Response: 200 OK if the product is updated, 404 Not Found otherwise.
    ///
    /// POST /api/Product/
    /// - Creates a new product.
    /// - Response: 201 Created with the created product.
    ///
    /// DELETE /api/Product/{id}
    /// - Deletes a product by its ID.
    /// - Response: 200 OK if the product is deleted, 404 Not Found otherwise.
    ///
    /// GET /api/Product/search/{search}
    /// - Searches for products by name.
    /// - Response: 200 OK with a list of matching products and search metadata.
    ///
    /// GET /api/aisearch/{search}
    /// - Searches for products using AI-based search.
    /// - Response: 200 OK with the search results, 404 Not Found otherwise.
    /// </remarks>
    public static void MapProductEndpoints(this IEndpointRouteBuilder routes)
    {
        var group = routes.MapGroup("/api/Product");

        group.MapGet("/", async (Context db) =>
        {
            return await db.Product.ToListAsync();
        })
        .WithName("GetAllProducts")
        .Produces<List<Product>>(StatusCodes.Status200OK);

        group.MapGet("/{id}", async (int id, Context db) =>
        {
            return await db.Product.AsNoTracking()
                .FirstOrDefaultAsync(model => model.Id == id)
                is Product model
                    ? Results.Ok(model)
                    : Results.NotFound();
        })
        .WithName("GetProductById")
        .Produces<Product>(StatusCodes.Status200OK)
        .Produces(StatusCodes.Status404NotFound);

        group.MapPut("/{id}", async (int id, Product product, Context db) =>
        {
            var affected = await db.Product
                .Where(model => model.Id == id)
                .ExecuteUpdateAsync(setters => setters
                  .SetProperty(m => m.Id, product.Id)
                  .SetProperty(m => m.Name, product.Name)
                  .SetProperty(m => m.Description, product.Description)
                  .SetProperty(m => m.Price, product.Price)
                  .SetProperty(m => m.ImageUrl, product.ImageUrl)
                );

            return affected == 1 ? Results.Ok() : Results.NotFound();
        })
        .WithName("UpdateProduct")
        .Produces(StatusCodes.Status404NotFound)
        .Produces(StatusCodes.Status204NoContent);

        group.MapPost("/", async (Product product, Context db) =>
        {
            db.Product.Add(product);
            await db.SaveChangesAsync();
            return Results.Created($"/api/Product/{product.Id}", product);
        })
        .WithName("CreateProduct")
        .Produces<Product>(StatusCodes.Status201Created);

        group.MapDelete("/{id}", async (int id, Context db) =>
        {
            var affected = await db.Product
                .Where(model => model.Id == id)
                .ExecuteDeleteAsync();

            return affected == 1 ? Results.Ok() : Results.NotFound();
        })
        .WithName("DeleteProduct")
        .Produces<Product>(StatusCodes.Status200OK)
        .Produces(StatusCodes.Status404NotFound);

        group.MapGet("/search/{search}", async (string search, Context db) =>
        {
            var stopwatch = new Stopwatch();
            stopwatch.Start();

            List<Product> products = await db.Product
            .Where(p => EF.Functions.Like(p.Name, $"%{search}%"))
            .ToListAsync();

            stopwatch.Stop();

            var response = new SearchResponse();
            response.Products = products;
            response.Response = products.Count > 0 ?
                $"{products.Count} Products found for [{search}]" :
                $"No products found for [{search}]";
            response.ElapsedTime = stopwatch.Elapsed;
            return response;
        })
            .WithName("SearchAllProducts")
            .Produces<List<Product>>(StatusCodes.Status200OK);

        #region AI Search Endpoint
        routes.MapGet("/api/aisearch/{search}",
            async (string search, Context db, MemoryContext mc) =>
            {
                var result = await mc.Search(search, db);
                return Results.Ok(result);
            })
            .WithName("AISearch")
            .Produces<SearchResponse>(StatusCodes.Status200OK)
            .Produces(StatusCodes.Status404NotFound);
        #endregion
    }
}


// File: F:\Dynamic\ExxerAi\ExxerAI\code\Samples\MicrosfotSamples\scenarios\04-chromadb\src\Products\Memory\MemoryContext.cs
﻿using ChromaDB.Client;
using DataEntities;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.VectorData;
using Newtonsoft.Json;
using OpenAI.Chat;
using OpenAI.Embeddings;
using Products.Models;
using SearchEntities;
using System.Text;
using VectorEntities;

namespace Products.Memory;

public class MemoryContext
{
    private const string SystemPrompt = "You are a useful assistant. You always reply with a short and funny message. If you do not know an answer, you say 'I don't know that.' You only answer questions related to outdoor camping products. For any other type of questions, explain to the user that you only answer outdoor camping products questions. Do not store memory of the chat conversation.";

    private readonly ILogger _logger;
    private readonly ChatClient? _chatClient;
    private readonly EmbeddingClient? _embeddingClient;

    private bool _isMemoryCollectionInitialized = false;
    private ChromaCollectionClient? _collectionClient;

    public MemoryContext(ILogger logger, ChatClient? chatClient, EmbeddingClient? embeddingClient, ChromaCollectionClient? collectionClient)
    {
        _logger = logger;
        _chatClient = chatClient;
        _embeddingClient = embeddingClient;
        _collectionClient = collectionClient;
    }

    public async Task<bool> InitMemoryContextAsync(Context db)
    {
        _logger.LogInformation("Get a copy of the list of products");
        var products = await db.Product.ToListAsync();

        _logger.LogInformation("Filling products in memory");

        var productIds = new List<string>();
        var productDescriptionEmbeddings = new List<ReadOnlyMemory<float>>();
        var productMetadata = new List<Dictionary<string, object>>();

        // iterate over the products and add them to the memory
        foreach (var product in products)
        {
            try
            {
                _logger.LogInformation("Adding product to memory: {Product}", product.Name);
                var productInfo = $"[{product.Name}] is a product that costs [{product.Price}] and is described as [{product.Description}]";
                var result = await _embeddingClient.GenerateEmbeddingAsync(productInfo);
                productIds.Add(product.Id.ToString());
                productDescriptionEmbeddings.Add(result.Value.ToFloats());
                _logger.LogInformation($"Product added to collections: {product.Name}");
            }
            catch (Exception exc)
            {
                _logger.LogError(exc, "Error adding product to memory");
            }
        }

        // add the products to the memory
        await _collectionClient.Upsert(productIds, productDescriptionEmbeddings, productMetadata);

        _logger.LogInformation("DONE! Filling products in memory");
        return true;
    }

    public async Task<SearchResponse> Search(string search, Context db)
    {
        if (!_isMemoryCollectionInitialized)
        {
            await InitMemoryContextAsync(db);
            _isMemoryCollectionInitialized = true;
        }

        var response = new SearchResponse
        {
            Response = $"I don't know the answer for your question. Your question is: [{search}]"
        };

        try
        {
            var resultGenEmbeddings = await _embeddingClient.GenerateEmbeddingAsync(search);
            var embeddingsSearchQuery = resultGenEmbeddings.Value.ToFloats();

            var searchOptions = new VectorSearchOptions<ProductVector>
            {
                Top = 3
            };

            // search the vector database for the most similar product        
            var queryResult = await _collectionClient.Query(
                queryEmbeddings: embeddingsSearchQuery,
                nResults: 2,
                include: ChromaQueryInclude.Metadatas | ChromaQueryInclude.Distances);

            var sbFoundProducts = new StringBuilder();
            int productPosition = 1;
            foreach (var result in queryResult)
            {
                if (result.Distance > 0.3)
                {
                    var foundProductId = int.Parse(result.Id);
                    var foundProduct = await db.FindAsync<Product>(foundProductId);
                    if (foundProduct != null)
                    {
                        response.Products.Add(foundProduct);
                        sbFoundProducts.AppendLine($"- Product {productPosition}:");
                        sbFoundProducts.AppendLine($"  - Name: {foundProduct.Name}");
                        sbFoundProducts.AppendLine($"  - Description: {foundProduct.Description}");
                        sbFoundProducts.AppendLine($"  - Price: {foundProduct.Price}");
                        productPosition++;
                    }
                }
            }

            // let's improve the response message
            var prompt = @$"You are an intelligent assistant helping clients with their search about outdoor products. 
Generate a catchy and friendly message using the information below.
Add a comparison between the products found and the search criteria.
Include products details.
    - User Question: {search}
    - Found Products: 
{sbFoundProducts}";

            var messages = new List<ChatMessage>
            {
                new SystemChatMessage(SystemPrompt),
                new UserChatMessage(prompt)
            };

            _logger.LogInformation("{ChatHistory}", JsonConvert.SerializeObject(messages));

            var resultPrompt = await _chatClient.CompleteChatAsync(messages);
            response.Response = resultPrompt.Value.Content[0].Text!;
        }
        catch (Exception ex)
        {
            // Handle exceptions (log them, rethrow, etc.)
            response.Response = $"An error occurred: {ex.Message}";
        }
        return response;
    }
}

