    /// </remarks>
    [JsonPropertyName("speedPriority")]
    public float? SpeedPriority { get; init; }

    /// <summary>
    /// Gets or sets how much to prioritize intelligence and capabilities when selecting a model.
    /// </summary>
    /// <remarks>
