                    pattern.AppendFormatted("(?<");
                    pattern.AppendFormatted(Regex.Escape(paramName));
                    pattern.AppendFormatted('>');
                    pattern.AppendFormatted(valueChars);
                    pattern.AppendFormatted(")?");
