﻿using ModelContextProtocol.Client;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Tests.Utils;

namespace ModelContextProtocol.Tests;

public class DockerEverythingServerTests(ITestOutputHelper testOutputHelper) : LoggedTest(testOutputHelper)
{
    /// <summary>Port number to be grabbed by the next test.</summary>
    private static int s_nextPort = 3000;

    // If the tests run concurrently against different versions of the runtime, tests can conflict with
    // each other in the ports set up for interacting with containers. Ensure that such suites running
    // against different TFMs use different port numbers.
    private static readonly int s_portOffset = 1000 * (Environment.Version.Major switch
    {
        int v when v >= 8 => Environment.Version.Major - 7,
        _ => 0,
    });

    private static int CreatePortNumber() => Interlocked.Increment(ref s_nextPort) + s_portOffset;

    public static bool IsDockerAvailable => EverythingSseServerFixture.IsDockerAvailable;

    [Fact(Skip = "docker is not available", SkipUnless = nameof(IsDockerAvailable))]
    [Trait("Execution", "Manual")]
    public async Task ConnectAndReceiveMessage_EverythingServerWithSse()
    {
        int port = CreatePortNumber();

        await using var fixture = new EverythingSseServerFixture(port);
        await fixture.StartAsync();

        var defaultOptions = new McpClientOptions
        {
            ClientInfo = new() { Name = "IntegrationTestClient", Version = "1.0.0" }
        };

        var defaultConfig = new SseClientTransportOptions
        {
            Endpoint = new Uri($"http://localhost:{port}/sse"),
            Name = "Everything",
        };

        // Create client and run tests
        await using var client = await McpClientFactory.CreateAsync(
            new SseClientTransport(defaultConfig),
            defaultOptions, 
            loggerFactory: LoggerFactory,
            cancellationToken: TestContext.Current.CancellationToken);
        var tools = await client.ListToolsAsync(cancellationToken: TestContext.Current.CancellationToken);

        // assert
        Assert.NotEmpty(tools);
    }

    [Fact(Skip = "docker is not available", SkipUnless = nameof(IsDockerAvailable))]
    [Trait("Execution", "Manual")]
    public async Task Sampling_Sse_EverythingServer()
    {
        int port = CreatePortNumber();

        await using var fixture = new EverythingSseServerFixture(port);
        await fixture.StartAsync();

        var defaultConfig = new SseClientTransportOptions
        {
            Endpoint = new Uri($"http://localhost:{port}/sse"),
            Name = "Everything",
        };

        int samplingHandlerCalls = 0;
        var defaultOptions = new McpClientOptions
        {
            Capabilities = new()
            {
                Sampling = new()
                {
                    SamplingHandler = async (_, _, _) =>
                    {
                        samplingHandlerCalls++;
                        return new CreateMessageResult
                        {
                            Model = "test-model",
                            Role = Role.Assistant,
                            Content = new TextContentBlock { Text = "Test response" },
                        };
                    },
                },
            },
        };

        await using var client = await McpClientFactory.CreateAsync(
            new SseClientTransport(defaultConfig),
            defaultOptions,
            loggerFactory: LoggerFactory,
            cancellationToken: TestContext.Current.CancellationToken);

        // Call the server's sampleLLM tool which should trigger our sampling handler
        var result = await client.CallToolAsync("sampleLLM", new Dictionary<string, object?>
            {
                ["prompt"] = "Test prompt",
                ["maxTokens"] = 100
            }, cancellationToken: TestContext.Current.CancellationToken);

        // assert
        Assert.NotNull(result);
        var textContent = Assert.Single(result.Content.OfType<TextContentBlock>());
        Assert.Equal("text", textContent.Type);
        Assert.False(string.IsNullOrEmpty(textContent.Text));
    }
}


// File: F:\Dynamic\ExxerAi\ExxerAI\code\Samples\ModelContextProtocolMS\csharp-sdk\tests\ModelContextProtocol.Tests\EverythingSseServerFixture.cs
﻿using System.Diagnostics;

namespace ModelContextProtocol.Tests;

public class EverythingSseServerFixture : IAsyncDisposable
{
    private readonly int _port;
    private readonly string _containerName;

    public static bool IsDockerAvailable => _isDockerAvailable ??= CheckIsDockerAvailable();
    private static bool? _isDockerAvailable;

    public EverythingSseServerFixture(int port)
    {
        _port = port;
        _containerName = $"mcp-everything-server-{_port}";
    }

    public async Task StartAsync()
    {
        var processStartInfo = new ProcessStartInfo
        {
            FileName = "docker",
            Arguments = $"run -p {_port}:3001 --name {_containerName} --rm tzolov/mcp-everything-server:v1",
            RedirectStandardInput = true,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
        };

        _ = Process.Start(processStartInfo)
            ?? throw new InvalidOperationException($"Could not start process for {processStartInfo.FileName} with '{processStartInfo.Arguments}'.");

        // Wait for the server to start
        await Task.Delay(10000);
    }
    public async ValueTask DisposeAsync()
    {
        try
        {

            // Stop the container
            var stopInfo = new ProcessStartInfo
            {
                FileName = "docker",
                Arguments = $"stop {_containerName}",
                UseShellExecute = false
            };

            using var stopProcess = Process.Start(stopInfo)
                ?? throw new InvalidOperationException($"Could not stop process for {stopInfo.FileName} with '{stopInfo.Arguments}'.");
            await stopProcess.WaitForExitAsync();
        }
        catch (Exception ex)
        {
            // Log the exception but don't throw
            await Console.Error.WriteLineAsync($"Error stopping Docker container: {ex.Message}");
        }
    }

    private static bool CheckIsDockerAvailable()
    {
        try
        {
            ProcessStartInfo processStartInfo = new()
            {
                FileName = "docker",
                // "docker info" returns a non-zero exit code if docker engine is not running.
                Arguments = "info",
                UseShellExecute = false,
            };

            using var process = Process.Start(processStartInfo);
            process?.WaitForExit();
            return process?.ExitCode is 0;
        }
        catch
        {
            return false;
        }
    }
}

