﻿using System.ComponentModel;
using ModelContextProtocol.Server;

namespace ExxerAi.MCPServer.Samples;

[McpServerToolType]
public static class WeatherTool
{
    [McpServerTool, Description("Returns the current weather for a specific city")]
    public static string GetWeatherForCity(string cityName)
    {
        Console.WriteLine("==========================");
        Console.WriteLine($"Function Start WeatherTool: GetWeatherForCity called with cityName: {cityName}");

        // generate a random weather report and return the result
        var random = new Random();
        var temperature = random.Next(-20, 40);
        var condition = random.Next(0, 2) == 0 ? "Sunny" : "Rainy";
        var humidity = random.Next(0, 100);
        var windSpeed = random.Next(0, 20);
        var report = $"Weather in {cityName}: {temperature}°C, {condition}, Humidity: {humidity}%, Wind Speed: {windSpeed} km/h";

        Console.WriteLine("Function report: " + report);
        Console.WriteLine($"Function End WeatherTool: GetWeatherForCity called with cityName: {cityName}");
        Console.WriteLine("==========================");

        return report;
    }
}


// File: F:\Dynamic\ExxerAi\ExxerAI\code\docs\ModelContextProtcolDocumentation\sample.cs
using ExxerAi.MCPServer.Components;
using ModelContextProtocol.Client;

namespace ExxerAi.MCPServer.Samples;

/// <summary>
/// Sample ASP.NET Core application that demonstrates how to set up a server-side
/// </summary>
public class Sample
{
    /// <summary>
    /// Returns a task that builds the ASP.NET Core application with the necessary services and configurations.
    /// </summary>
    /// <returns></returns>
    public static Task BuilderAsync()
    {
        var builder = WebApplication.CreateBuilder();

        // Add services to the container.
        builder.Services.AddRazorComponents()
            .AddInteractiveServerComponents();

        // Add configuration service
        builder.Services.AddSingleton<IConfiguration>(builder.Configuration);

        // Add logging service
        builder.Services.AddLogging(loggingBuilder =>
        {
            loggingBuilder.AddConsole();
            loggingBuilder.AddDebug();
        });

        builder.Services.AddSingleton<ILogger>(sp => sp.GetRequiredService<ILogger<Sample>>());

        // add MCP client
        builder.Services.AddSingleton<IMcpClient>(sp =>
        {
            McpClientOptions mcpClientOptions = new()
            { ClientInfo = new() { Name = "AspNetCoreSseClient", Version = "1.0.0" } };

            HttpClient httpClient = new()
            {
                BaseAddress = new("https://localhost:7133/sse")  //"https +http://aspnetsseserver" + "/sse")
            };

            McpServerConfig mcpServerConfig = new()
            {
                Id = "AspNetCoreSse",
                Name = "AspNetCoreSse",
                TransportType = TransportTypes.Sse,
                Location = httpClient.BaseAddress.ToString(),
            };

            var mcpClient = McpClientFactory.CreateAsync(mcpServerConfig, mcpClientOptions).GetAwaiter().GetResult();
            return mcpClient;
        });

        var app = builder.Build();

        // Configure the HTTP request pipeline.
        if (!app.Environment.IsDevelopment())
        {
            app.UseExceptionHandler("/Error", createScopeForErrors: true);
            // The default HSTS value is 30 days. You may want to change this for production scenarios, see https://aka.ms/aspnetcore-hsts.
            app.UseHsts();
        }

        app.UseHttpsRedirection();

        app.UseAntiforgery();

        app.MapStaticAssets();
        app.MapRazorComponents<App>()
            .AddInteractiveServerRenderMode();

        app.Run();
        return Task.CompletedTask;
    }
}

// File: F:\Dynamic\ExxerAi\ExxerAI\code\mcp\Common\Polyfills\System\Collections\Generic\CollectionExtensions.cs
using ModelContextProtocol;

namespace System.Collections.Generic;

internal static class CollectionExtensions
{
    public static TValue? GetValueOrDefault<TKey, TValue>(this IReadOnlyDictionary<TKey, TValue> dictionary, TKey key)
    {
        return dictionary.GetValueOrDefault(key, default!);
    }

    public static TValue GetValueOrDefault<TKey, TValue>(this IReadOnlyDictionary<TKey, TValue> dictionary, TKey key, TValue defaultValue)
    {
        Throw.IfNull(dictionary);

        return dictionary.TryGetValue(key, out TValue? value) ? value : defaultValue;
    }

    public static Dictionary<TKey, TValue> ToDictionary<TKey, TValue>(this IEnumerable<KeyValuePair<TKey, TValue>> source) =>
        source.ToDictionary(kv => kv.Key, kv => kv.Value);
}

