        ResourceTemplate resource = new()
        {
            UriTemplate = options?.UriTemplate ?? DeriveUriTemplate(name, function),
            Name = name,
            Title = options?.Title,
            Description = options?.Description,
            MimeType = options?.MimeType ?? "application/octet-stream",
        };

