using System.Text.RegularExpressions;
using ExxerAI.Application.DTOs;
using ExxerAI.Application.Enums;
using ExxerAI.Domain.DocumentProcessing;

namespace ExxerAI.Application.Patterns;

/// <summary>
/// OCR region-specific extraction pattern
/// Based on KpiExxerpro region extraction with OpenCV contour detection
/// </summary>
public class OCRRegionPattern : ExtractionPattern
{


    /// <summary>
    /// Gets or sets the reference text to locate the region
    /// </summary>
    public string ReferenceText { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the search strategy for finding the target text
    /// </summary>
    public SearchStrategy SearchStrategy { get; set; }

    /// <summary>
    /// Gets or sets the region bounds relative to reference text
    /// </summary>
    public RegionBounds RegionBounds { get; set; } = new();

    /// <summary>
    /// Extracts field value using OCR region-specific processing
    /// This is a simplified implementation - full OCR integration would be in infrastructure layer
    /// </summary>
    /// <param name="text">Text to extract from (or OCR input)</param>
    /// <param name="context">Processing context with OCR capabilities</param>
    /// <returns>Extracted value or null if not found</returns>
    public override string? ExtractValue(string text, ExtractionContext context)
    {
        // This would typically integrate with OCR services in the infrastructure layer
        // For now, implement as text-based search as fallback
        var lines = text.Split('\n', StringSplitOptions.RemoveEmptyEntries);

        for (int i = 0; i < lines.Length; i++)
        {
            if (lines[i].Contains(ReferenceText, StringComparison.OrdinalIgnoreCase))
            {
                return SearchStrategy switch
                {
                    SearchStrategy.NextToken => ExtractNextToken(lines[i]),
                    SearchStrategy.NextLineInRegion => i + 1 < lines.Length ? ExtractFromLine(lines[i + 1]) : null,
                    SearchStrategy.SameLineOrNext => ExtractFromLine(lines[i]) ?? (i + 1 < lines.Length ? ExtractFromLine(lines[i + 1]) : null),
                    _ => null
                };
            }
        }

        return null;
    }

    private string? ExtractNextToken(string line)
    {
        var tokens = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        var refIndex = Array.FindIndex(tokens, t => t.Contains(ReferenceText, StringComparison.OrdinalIgnoreCase));
        return refIndex >= 0 && refIndex + 1 < tokens.Length ? tokens[refIndex + 1] : null;
    }

    private string? ExtractFromLine(string line)
    {
        // Simple extraction - would be enhanced with more sophisticated parsing
        var match = Regex.Match(line, @"[\d,]+\.?\d*");
        return match.Success ? match.Value : null;
    }
} 

// File: F:\Dynamic\ExxerAi\ExxerAI\code\src\ExxerAI.Application\Services\AgentService.cs
using ExxerAI.Application.Interfaces;
using ExxerAI.Domain.Entities;
using ExxerAI.Domain.Helpers;

namespace ExxerAI.Application.Services;

/// <summary>
/// Service implementation for managing agents in the ExxerAI system
/// </summary>
public class AgentService : IAgentService
{
    private readonly IAgentRepository _agentRepository;
    private readonly ITaskRepository _taskRepository;

    /// <summary>
    /// Initializes a new instance of the AgentService class
    /// </summary>
    /// <param name="agentRepository">The agent repository</param>
    /// <param name="taskRepository">The task repository</param>
    public AgentService(
        IAgentRepository agentRepository,
        ITaskRepository taskRepository)
    {
        _agentRepository = agentRepository ?? throw new ArgumentNullException(nameof(agentRepository));
        _taskRepository = taskRepository ?? throw new ArgumentNullException(nameof(taskRepository));
    }

    /// <summary>
    /// Creates a new agent
    /// </summary>
    /// <param name="name">The agent name</param>
    /// <param name="description">The agent description</param>
    /// <param name="capabilities">The agent capabilities</param>
    /// <param name="cancellationToken">Cancellation token</param>
    /// <returns>The result of the operation containing the created agent</returns>
    public async Task<Result<Agent>> CreateAgentAsync(
        string name,
        string description,
        AgentCapabilities capabilities,
        CancellationToken cancellationToken = default)
    {
        try
        {
            if (string.IsNullOrWhiteSpace(name))
            {
                return Result<Agent>.WithFailure("Agent name cannot be empty");
            }

            if (string.IsNullOrWhiteSpace(description))
            {
                return Result<Agent>.WithFailure("Agent description cannot be empty");
            }

            if (capabilities == null)
            {
                return Result<Agent>.WithFailure("Agent capabilities cannot be null");
            }

            var agent = new Agent
            {
                Name = name,
                Description = description,
                Capabilities = capabilities,
                Configuration = new AgentConfiguration(),
                Status = AgentStatus.Active
            };

            var addResult = await _agentRepository.AddAsync(agent, cancellationToken).ConfigureAwait(false);

            if (addResult.IsFailure)
            {
                return Result<Agent>.WithFailure(addResult.Error ?? "Failed to add agent");
            }

            return addResult;
        }
        catch (Exception ex)
        {
            return Result<Agent>.WithFailure($"An error occurred while creating the agent: {ex.Message}");
        }
    }

    /// <summary>
    /// Gets an agent by its identifier
    /// </summary>
    /// <param name="agentId">The agent identifier</param>
    /// <param name="cancellationToken">Cancellation token</param>
    /// <returns>The result of the operation containing the agent if found</returns>
    public async Task<Result<Agent>> GetAgentAsync(Guid agentId, CancellationToken cancellationToken = default)
    {
        try
        {
            if (agentId == Guid.Empty)
            {
                return Result<Agent>.WithFailure("Agent ID cannot be empty");
            }

            var result = await _agentRepository.GetByIdAsync(agentId, cancellationToken).ConfigureAwait(false);

            if (result.IsFailure)
            {
                return Result<Agent>.WithFailure($"Agent not found with ID: {agentId}");
            }

            return result;
        }
        catch (Exception ex)
        {
            return Result<Agent>.WithFailure($"An error occurred while retrieving the agent: {ex.Message}");
        }
    }

    /// <summary>
    /// Gets all agents
    /// </summary>
    /// <param name="cancellationToken">Cancellation token</param>
    /// <returns>The result of the operation containing all agents</returns>
    public async Task<Result<IEnumerable<Agent>>> GetAllAgentsAsync(CancellationToken cancellationToken = default)
    {
        try
        {
            var result = await _agentRepository.GetAllAsync(cancellationToken).ConfigureAwait(false);

            if (result.IsFailure)
            {
                return Result<IEnumerable<Agent>>.WithFailure(result.Error ?? "Failed to retrieve agents");
