    public async Task<int> GetDocumentsProcessedThisWeekAsync(CancellationToken cancellationToken)
    {
        // Simulate metric calculation
        await Task.Delay(10, cancellationToken);
        return Random.Shared.Next(0, 300);
    }

    /// <summary>
