        // Assert - ApiResponse
        apiResponse.Success.ShouldBeFalse();
        apiResponse.Data.ShouldBeNull();
        apiResponse.Errors.ShouldNotBeNull();
        apiResponse.Message.ShouldBe(string.Empty);
    }
