// File: F:\Dynamic\ExxerAi\ExxerAI\code\src\tests\ExxerAI.Architecture.Tests\ClassDuplicationTests.cs
using System.Reflection;
using NetArchTest.Rules;

namespace ExxerAI.Architecture.Tests;

public class ClassDuplicationTests
{
    [Fact]
    public void All_Classes_Should_Not_Have_Duplicate_Names_In_Different_Namespaces()
    {
        // Load the assembly to be tested
        var assembly = Assembly.Load("ExxerAI.Domain"); // Replace with your specific assembly name

        // Find all types in the assembly
        var types = Types.InAssembly(assembly)
            .That()
            .AreClasses()
            .GetTypes();

        // Group by class name and check for duplicates in different namespaces
        var duplicates = types.GroupBy(t => t.Name)
            .Where(g => g.Count() > 1) // Find groups with more than one class with the same name
            .Select(g => new { ClassName = g.Key, Namespaces = g.Select(t => t.Namespace).Distinct() })
            .Where(g => g.Namespaces.Count() > 1) // Check if the same class name exists in more than one namespace
            .ToList();

        // Assert that there are no duplicated class names across different namespaces
        Assert.Empty(duplicates);
    }
}

// File: F:\Dynamic\ExxerAi\ExxerAI\code\src\tests\ExxerAI.Architecture.Tests\EnumModelTests.cs
using System.Reflection;
using NetArchTest.Rules;

namespace ExxerAI.Architecture.Tests;

public class EnumModelTests
{
    [Fact]
    public void All_Enumerations_Should_Not_Have_Duplicate_Ids()
    {
        var types = Types.InAssembly(Assembly.Load("ExxerAI.Domain"))
            .That()
            .ResideInNamespace("ExxerAI.Domain.Enums")
            .And()
            .Inherit(typeof(EnumModel))
            .GetTypes();

        foreach (var type in types)
        {
            var instances = type.GetFields(BindingFlags.Public | BindingFlags.Static | BindingFlags.FlattenHierarchy)
                .Where(f => f.FieldType == type)
                .Select(f => f.GetValue(null))
                .Cast<EnumModel>()
                .ToList();

            var ids = instances.Select(e => e.Value).ToList();
            Assert.Equal(ids.Count, ids.Distinct().Count());
        }
    }

    [Fact]
    public void All_Enumerations_Should_Not_Have_Duplicate_Names()
    {
        var types = Types.InAssembly(Assembly.Load("ExxerAI.Domain"))
            .That()
            .ResideInNamespace("ExxerAI.Domain.Enums")
            .And()
            .Inherit(typeof(EnumModel))
            .GetTypes();

        foreach (var type in types)
        {
            var instances = type.GetFields(BindingFlags.Public | BindingFlags.Static | BindingFlags.FlattenHierarchy)
                .Where(f => f.FieldType == type)
                .Select(f => f.GetValue(null))
                .Cast<EnumModel>()
                .ToList();

            var names = instances.Select(e => e.Name).ToList();
            Assert.Equal(names.Count, names.Distinct().Count());
        }
    }
}

