        options.OCRLanguages.ShouldContain("deu");
        options.CustomParameters.Count.ShouldBe(2);
        options.CustomParameters["MaxProcessingTime"].ShouldBe(5000);
        options.CustomParameters["EnableDebugMode"].ShouldBe(true);
    }
