            // Act
            var result = ResultExtensions.EnsureNotNull(nullValue, "testParam");

            // Assert
            result.IsFailure.ShouldBeTrue();
            result.Error!.ShouldContain("Parameter 'testParam' cannot be null");
        }

        [Fact]
