            {
                ((object?)"value1", "param1"),
                ((object?)42, "param2"),
                ((object?)new object(), "param3")
            };

            // Act
            var result = ResultExtensions.ValidateNotNull(validations);

            // Assert
            result.IsSuccess.ShouldBeTrue();
        }

        [Fact]
        public void ValidateNotNull_WithSomeNullValues_ShouldReturnFailure()
        {
            // Arrange
