        }

        [Fact]
        public void EnsureNotNull_WithNullOrEmptyParameterName_ShouldReturnFailure()
        {
            var resultNull = ResultExtensions.EnsureNotNull("value", null);
            var resultEmpty = ResultExtensions.EnsureNotNull("value", "");
