			var expectedResult = "✅ Started watching Google Drive folder: Test Folder";
			
			_mockGoogleDriveService.StartFolderWatchAsync(Arg.Any<string>(), Arg.Any<bool>(), Arg.Any<bool>(), Arg.Any<int>())
